String normalized = null;
if (ctx.containsKey('level')) {
  def level = ctx.level;
  if (level instanceof Number) {
    def map = new HashMap();
    map.put(10, 'trace');
    map.put(20, 'debug');
    map.put(30, 'info');
    map.put(40, 'warn');
    map.put(50, 'error');
    map.put(60, 'fatal');
    normalized = map.getOrDefault(((Number) level).intValue(), 'unknown');
  } else {
    normalized = level.toString().toLowerCase();
  }
} else if (ctx.containsKey('severity')) {
  normalized = ctx.severity.toString().toLowerCase();
} else if (ctx.containsKey('message') && ctx.message != null) {
  String msg = ctx.message.toString().toLowerCase();
  if (msg.contains('error') || msg.contains('failed') || msg.contains('exception')) {
    normalized = 'error';
  } else if (msg.contains('warn')) {
    normalized = 'warn';
  } else if (msg.contains('debug')) {
    normalized = 'debug';
  } else {
    normalized = 'info';
  }
} else {
  normalized = 'info';
}
if (normalized == 'warning') {
  normalized = 'warn';
}
if (normalized == 'err') {
  normalized = 'error';
}
ctx.log = ctx.containsKey('log') && ctx.log instanceof Map ? ctx.log : new HashMap();
ctx.log.put('level', normalized);
ctx.log_level = normalized;
